class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" -- "*" Furniture : consists of
Furniture "*" -- "*" ComponentType : is composed of
Furniture "*" -- "*" ComponentType : uses
Store "1" -- "*" Order : places
Order "*" -- "*" Furniture : contains
Order "*" -- "1" Store : placed by
Order "1" -- "*" OrderLine : contains
OrderLine "*" -- "1" Furniture : refers to

@enduml

